using System.Threading.Tasks;
using Microsoft.CodeAnalysis.CSharp.Testing;
using Microsoft.CodeAnalysis.Testing;
using Xunit;

namespace Varve.Analyzers.Tests;

/// <summary>
/// VARVE0006. The Web UI's levels as a dependency rule (ADR 0206 point 4): the
/// level order, and services against models.
/// </summary>
/// <remarks>
/// Every sample is written as Razor writes it: a generated file, marked
/// <c>&lt;auto-generated/&gt;</c>, that renders a component through
/// <c>OpenComponent&lt;T&gt;</c> with its name fully qualified. An analyzer that
/// does not opt into generated code reports nothing in such a file, so every
/// violating sample here is also the proof that this rule opts in.
/// </remarks>
public class ComponentLevelAnalyzerTests
{
    // Just enough of Blazor and of the client for the rule to resolve: the
    // component interface, the builder Razor calls, a service and a model.
    private const string Framework = """
        namespace Microsoft.AspNetCore.Components
        {
            public interface IComponent { }
            public abstract class ComponentBase : IComponent { }
        }

        namespace Microsoft.AspNetCore.Components.Rendering
        {
            public sealed class RenderTreeBuilder
            {
                public void OpenComponent<TComponent>(int sequence) where TComponent : Microsoft.AspNetCore.Components.IComponent { }
                public void CloseComponent() { }
            }
        }

        namespace Varve.Protocol.Client
        {
            public sealed class VarveHealthClient { }
        }

        namespace Varve.Protocol.Client.Model
        {
            public sealed class Problem { }
        }
        """;

    // One component per level, each rendering nothing, for samples to render.
    private const string OnePerLevel = """
        // <auto-generated/>
        namespace Varve.WebUi.Atoms { public partial class Button : global::Microsoft.AspNetCore.Components.ComponentBase { } }
        namespace Varve.WebUi.Molecules { public partial class Notice : global::Microsoft.AspNetCore.Components.ComponentBase { } }
        namespace Varve.WebUi.Organisms { public partial class Panel : global::Microsoft.AspNetCore.Components.ComponentBase { } }
        namespace Varve.WebUi.Templates { public partial class Shell : global::Microsoft.AspNetCore.Components.ComponentBase { } }
        namespace Varve.WebUi.Parts { public partial class ProblemView : global::Microsoft.AspNetCore.Components.ComponentBase { } }
        namespace Varve.WebUi.Pages { public partial class Health : global::Microsoft.AspNetCore.Components.ComponentBase { } }
        """;

    private static string Component(string level, string name, string body) => $$"""
        // <auto-generated/>
        #pragma warning disable 1591
        namespace Varve.WebUi.{{level}}
        {
            public partial class {{name}} : global::Microsoft.AspNetCore.Components.ComponentBase
            {
                protected void BuildRenderTree(global::Microsoft.AspNetCore.Components.Rendering.RenderTreeBuilder __builder)
                {
                    {{body}}
                }
            }
        }
        """;

    [Fact]
    public Task A_parameter_set_by_nameof_is_one_use_reported_once() =>
        RunAsync(Component("Atoms", "Sample",
            "__builder.OpenComponent<global::Varve.WebUi.Atoms.{|VARVE0006:Button|}>(0); string p = nameof(global::Varve.WebUi.Atoms.Button.ToString); __builder.CloseComponent();"));

    private static string Renders(string level, string name) =>
        "__builder.OpenComponent<global::Varve.WebUi." + level + "." + name + ">(0); __builder.CloseComponent();";

    private static string RendersMarked(string level, string name) =>
        "__builder.OpenComponent<global::Varve.WebUi." + level + ".{|VARVE0006:" + name + "|}>(0); __builder.CloseComponent();";

    private static Task RunAsync(params string[] sources)
    {
        Test test = new();
        test.TestState.Sources.Add(("Framework.cs", Framework));
        test.TestState.Sources.Add(("Levels.g.cs", OnePerLevel));

        for (int i = 0; i < sources.Length; i++)
        {
            test.TestState.Sources.Add(("Sample" + i + "_razor.g.cs", sources[i]));
        }

        return test.RunAsync(TestContext.Current.CancellationToken);
    }

    // The level order: a conforming sample renders the level below; a violating
    // one renders its own level, at every level.
    [Theory]
    [InlineData("Molecules", "Atoms", "Button")]
    [InlineData("Organisms", "Molecules", "Notice")]
    [InlineData("Templates", "Organisms", "Panel")]
    [InlineData("Parts", "Templates", "Shell")]
    [InlineData("Pages", "Parts", "ProblemView")]
    public Task A_component_rendering_the_level_below_is_clean(string level, string below, string used) =>
        RunAsync(Component(level, "Sample", Renders(below, used)));

    [Theory]
    [InlineData("Atoms", "Button")]
    [InlineData("Molecules", "Notice")]
    [InlineData("Organisms", "Panel")]
    [InlineData("Templates", "Shell")]
    [InlineData("Parts", "ProblemView")]
    [InlineData("Pages", "Health")]
    public Task A_component_rendering_its_own_level_is_reported(string level, string used) =>
        RunAsync(Component(level, "Sample", RendersMarked(level, used)));

    [Fact]
    public Task An_atom_rendering_no_component_is_clean() =>
        RunAsync(Component("Atoms", "Sample", "__builder.CloseComponent();"));

    [Theory]
    [InlineData("Atoms", "Pages", "Health")]
    [InlineData("Molecules", "Organisms", "Panel")]
    [InlineData("Templates", "Parts", "ProblemView")]
    [InlineData("Parts", "Pages", "Health")]
    public Task A_component_rendering_a_higher_level_is_reported(string level, string higher, string used) =>
        RunAsync(Component(level, "Sample", RendersMarked(higher, used)));

    // Services against models: a service only in Pages, a model in Parts and
    // Pages, neither below.
    [Fact]
    public Task A_page_using_the_clients_service_and_model_is_clean() =>
        RunAsync(Component("Pages", "Sample", "global::Varve.Protocol.Client.VarveHealthClient s = null; global::Varve.Protocol.Client.Model.Problem p = null;"));

    [Fact]
    public Task A_part_using_the_clients_model_is_clean() =>
        RunAsync(Component("Parts", "Sample", "global::Varve.Protocol.Client.Model.Problem p = null;"));

    [Fact]
    public Task A_part_using_the_clients_service_is_reported() =>
        RunAsync(Component("Parts", "Sample", "global::Varve.Protocol.Client.{|VARVE0006:VarveHealthClient|} s = null;"));

    [Theory]
    [InlineData("Atoms")]
    [InlineData("Molecules")]
    [InlineData("Organisms")]
    [InlineData("Templates")]
    public Task A_level_below_parts_using_the_clients_model_or_service_is_reported(string level) =>
        RunAsync(Component(level, "Sample", "global::Varve.Protocol.Client.Model.{|VARVE0006:Problem|} p = null; global::Varve.Protocol.Client.{|VARVE0006:VarveHealthClient|} s = null;"));

    // The model holds values only: it names no service, with or without Blazor.
    private const string ClientOnly = """
        namespace Varve.Protocol.Client
        {
            public sealed class VarveHealthClient { }
            public sealed class ClientLimits { }
        }

        namespace Varve.Protocol.Client.Model
        {
            public sealed class Problem { }
        }
        """;

    private static Task RunClientAsync(string source)
    {
        CSharpAnalyzerTest<ComponentLevelAnalyzer, DefaultVerifier> test = new() { ReferenceAssemblies = ReferenceAssemblies.Net.Net80 };
        test.TestState.Sources.Add(("Client.cs", ClientOnly));
        test.TestState.Sources.Add(("Sample.cs", source));
        return test.RunAsync(TestContext.Current.CancellationToken);
    }

    [Fact]
    public Task A_model_type_naming_other_model_types_is_clean() =>
        RunClientAsync("namespace Varve.Protocol.Client.Model { public sealed record Readiness(Problem Problem); }");

    [Fact]
    public Task A_model_type_naming_a_service_type_is_reported() =>
        RunClientAsync("namespace Varve.Protocol.Client.Model { public sealed record Readiness(global::Varve.Protocol.Client.{|VARVE0006:VarveHealthClient|} Client); }");

    [Fact]
    public Task A_model_type_naming_a_value_outside_the_model_is_reported() =>
        RunClientAsync("namespace Varve.Protocol.Client.Model.Health { public static class Limits { public static global::Varve.Protocol.Client.{|VARVE0006:ClientLimits|} Default => null; } }");

    [Fact]
    public Task A_service_naming_the_model_is_clean() =>
        RunClientAsync("namespace Varve.Protocol.Client { public sealed class Reader { public global::Varve.Protocol.Client.Model.Problem Read() => null; } }");

    [Fact]
    public Task The_model_message_names_both_types()
    {
        CSharpAnalyzerTest<ComponentLevelAnalyzer, DefaultVerifier> test = new() { ReferenceAssemblies = ReferenceAssemblies.Net.Net80 };
        test.TestState.Sources.Add(("Client.cs", ClientOnly));
        test.TestState.Sources.Add(("Sample.cs", "namespace Varve.Protocol.Client.Model { public sealed class Sample { private global::Varve.Protocol.Client.{|#0:VarveHealthClient|} client; } }"));
        test.ExpectedDiagnostics.Add(new DiagnosticResult(VarveDiagnostics.ComponentLevel)
            .WithLocation(0)
            .WithArguments(
                "Varve.Protocol.Client.Model.Sample",
                "Varve.Protocol.Client.Model",
                "names the client's service type 'Varve.Protocol.Client.VarveHealthClient', which the model never names",
                ComponentLevelAnalyzer.ModelNamesServiceDecide));
        return test.RunAsync(TestContext.Current.CancellationToken);
    }

    // What the rule does not count.
    [Fact]
    public Task A_type_of_its_own_level_that_is_not_a_component_is_clean() =>
        RunAsync(
            "namespace Varve.WebUi.Organisms { public sealed record CommitEntry(string Position); }",
            Component("Organisms", "Sample", "global::Varve.WebUi.Organisms.CommitEntry entry = new(\"7\");"));

    [Fact]
    public Task A_component_naming_itself_and_a_documentation_reference_are_clean() =>
        RunAsync("""
            namespace Varve.WebUi.Molecules
            {
                /// <summary>Takes <see cref="Notice"/>s as its content.</summary>
                public partial class Sample : global::Microsoft.AspNetCore.Components.ComponentBase
                {
                    private static Sample Self() => null;
                }
            }
            """);

    [Fact]
    public Task A_type_outside_the_levels_is_not_checked() =>
        RunAsync("""
            // <auto-generated/>
            namespace Varve.WebUi
            {
                public partial class App : global::Microsoft.AspNetCore.Components.ComponentBase
                {
                    private System.Type layout = typeof(global::Varve.WebUi.Pages.Health);
                    private global::Varve.Protocol.Client.VarveHealthClient client;
                }
            }
            """);

    [Fact]
    public Task A_compilation_without_blazor_is_not_checked()
    {
        CSharpAnalyzerTest<ComponentLevelAnalyzer, DefaultVerifier> test = new() { ReferenceAssemblies = ReferenceAssemblies.Net.Net80 };
        test.TestState.Sources.Add("namespace Varve.WebUi.Atoms { public class A { } public class B { A a; } }");
        return test.RunAsync(TestContext.Current.CancellationToken);
    }

    [Fact]
    public Task The_message_names_both_components_and_both_levels()
    {
        Test test = new();
        test.TestState.Sources.Add(("Framework.cs", Framework));
        test.TestState.Sources.Add(("Levels.g.cs", OnePerLevel));
        test.TestState.Sources.Add(("Sample_razor.g.cs", Component("Parts", "Sample", "__builder.OpenComponent<global::Varve.WebUi.Parts.{|#0:ProblemView|}>(0);")));
        test.ExpectedDiagnostics.Add(new DiagnosticResult(VarveDiagnostics.ComponentLevel)
            .WithLocation(0)
            .WithArguments(
                "Varve.WebUi.Parts.Sample",
                "Parts",
                "uses the component 'Varve.WebUi.Parts.ProblemView' of level Parts, which is not below its own",
                ComponentLevelAnalyzer.SameOrHigherDecide));
        return test.RunAsync(TestContext.Current.CancellationToken);
    }

    private sealed class Test : CSharpAnalyzerTest<ComponentLevelAnalyzer, DefaultVerifier>
    {
        public Test() => ReferenceAssemblies = ReferenceAssemblies.Net.Net80;
    }
}
